        private static string GetBullBullLayout(string sDesc, string slang, string GameId3rd, string gameId)
        {
            var gameName = refDataHelper.GetResourceDataByRefIdAndResourceId(GameTypeRefKey, gameId.ToString(), slang, string.Empty);
            var GameDetail = sDesc.Split('*');
            var result = GetSplitValue('=', GameDetail[4]);

            var resultTitle = result.Split(':')[0].Split(';')[0].Replace("B", "Banker").Replace("P", "Player");
            var resultCards = result.Split(':')[0].Replace("B;", "").Replace("P;", "").Replace(";", ",").Replace("0", "").Replace("S12", "SA");
            var player1Cards = result.Split(':')[1].Replace("P1;", "").Replace(";", ",").Replace("0", "").Replace("S12", "SA");
            var player2Cards = result.Split(':')[2].Replace("P2;", "").Replace(";", ",").Replace("0", "").Replace("S12", "SA");
            var player3Cards = result.Split(':')[3].Replace("P3;", "").Replace(";", ",").Replace("0", "").Replace("S12", "SA");

            player1Cards = player1Cards.Split(',').Length >= 5 ? player1Cards.Insert(5, "<br/>") : player1Cards;
            player2Cards = player2Cards.Split(',').Length >= 5 ? player2Cards.Insert(5, "<br/>") : player2Cards;
            player3Cards = player3Cards.Split(',').Length >= 5 ? player3Cards.Insert(5, "<br/>") : player3Cards;
            var strFinalLayout = GetFinalLayout(gameId);

            return String.Format(strFinalLayout,
                $"{GameNameText} {gameName}",
                $"{GameIdText} {GameId3rd}",
                $"{resultTitle}: ",
                GetCardImgPath(resultCards),
                $"Player1",
                GetCardImgPath(player1Cards),
                $"Player2",
                GetCardImgPath(player2Cards),
                $"Player3",
                GetCardImgPath(player3Cards));
        }

