        private static string GetCardImgPath(string CardValue)
        {
            string SkinPath = (_ImgPath == "") ? @"template/public/game_result/" : _ImgPath;
            string strCardImg = "";
            string[] strCard = CardValue.Split(',');
            for (int j = 0; j < strCard.Length; j++)
            {
                if (!string.IsNullOrEmpty(strCard[j]))
                {
                    if (strCard[j].Contains("<br/>"))
                    {
                        strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString().Replace("<br/>", "") + ".png' align='absmiddle' border='0' class='code' />";
                        strCardImg += "<br/>";
                    }
                    else
                    {
                        strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString() + ".png' align='absmiddle' border='0' class='code' />";
                    }
                }
            }
            return strCardImg;
        }

        private static string GenImgUrl(string sMode, string sResult)
        {
            var sImgUrl = "";
            var skinroot_path = (_ImgPath == "") ? @"template\public\game_result\" : _ImgPath;
            skinroot_path += $"{sMode}\\";
            if (sMode == "FanTan")
            {
                var numberBall = int.Parse(sResult);
                for (int j = 0; j < numberBall; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + "ball.png\"  align=\"absmiddle\" border=\"0\"  height=\"38\" width=\"38\"/>";
                }
            }
            else
            {
                string[] strResult = sResult.Split(';');
                for (int j = 0; j < strResult.Length; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + strResult[j].ToString() + ".png\"  align=\"absmiddle\" border=\"0\" height=\"38\" width=\"38\"/>";
                }
            }

            return sImgUrl;
        }

        private static string GetFinalLayout(string gameId)
        {
            string strFinalLayout = "";
            switch (gameId)
            {
                case GameIdConstants.Baccarat:
                case GameIdConstants.InsuranceBaccarat:
                case GameIdConstants.InRunningBaccarat:
                case GameIdConstants.DragonTiger:
                case GameIdConstants.ThreeCardPoker:
                    strFinalLayout = "<div class='popWTableArea'><table width='100%' cellpadding='0' cellspacing='0' border='0' class='oddsTable info'>";
                    strFinalLayout += "<tbody><tr><td colspan='2' class='tabtitle' align='left'>{0}</td></tr></tbody>";
                    strFinalLayout += "<tbody><tr><td colspan='2' class='tabtitle' align='left'>{1}</td></tr></tbody>";
                    strFinalLayout += "<tbody>";
                    strFinalLayout += "<tr align='center'><th>{2}</th><th>{3}</th></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td width='50%'>{4}</td><td width='50%'>{5}</td></tr>";
                    strFinalLayout += "</tbody></table></div>";
                    break;
                case GameIdConstants.Roulette:
                case GameIdConstants.SicBo:
                case GameIdConstants.SeDie:
                case GameIdConstants.HiLo:
                case GameIdConstants.FishPrawnCragDice:
                case GameIdConstants.FanTan:
                    strFinalLayout = "<div class='popWTableArea'><table width='100%' cellpadding='0' cellspacing='0' border='0' class='oddsTable info'>";
                    strFinalLayout += "<tbody><tr><td class='tabtitle' align='left'>{0}</td></tr></tbody>";
                    strFinalLayout += "<tbody><tr><td class='tabtitle' align='left'>{1}</td></tr></tbody>";
                    strFinalLayout += "<tbody>";
                    strFinalLayout += "<tr align='center'><th>{2}</th></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td>{3}</td></tr>";
                    strFinalLayout += "</tbody></table></div>";
                    break;
                case GameIdConstants.BullBull:
                case GameIdConstants.FightingBullBull:
                case GameIdConstants.ThreeFace:
                case GameIdConstants.WenzhouPaiGow:
                    strFinalLayout = "<div class='popWTableArea'><table width='100%' cellpadding='0' cellspacing='0' border='0' class='oddsTable info'>";
                    strFinalLayout += "<tbody><tr><td class='tabtitle' colspan='3' align='left'>{0}</td></tr></tbody>";
                    strFinalLayout += "<tbody><tr><td class='tabtitle' colspan='3' align='left'>{1}</td></tr></tbody>";
                    strFinalLayout += "<tbody><tr align='center'><td colspan='3'>{2} {3}</td></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td>{4}<br/>{5}</td>";
                    strFinalLayout += "<td>{6}<br/>{7}</td>";
                    strFinalLayout += "<td>{8}<br/>{9}</td></tr>";

                    break;
            }
            return strFinalLayout;
        }

